391	  USING (
392	    (user_id = auth.uid())
393	    OR (account_id IS NOT NULL AND is_account_member(account_id) AND has_app_access(account_id, app_id))
394	  );
395	CREATE POLICY activity_log_insert ON activity_log FOR INSERT TO authenticated
396	  WITH CHECK (
397	    user_id = auth.uid()
398	    AND app_id = get_app_id('rankora')
399	  );
